const object=x=>x&&typeof x==='object'&&!Array.isArray(x)?x:{};
const validProgress=value=>{const x=object(value),out={};for(const key of ['completed','quizzes','guides','projects','labs','gates'])out[key]=Object.fromEntries(Object.entries(object(x[key])).filter(([k,v])=>k.length<=160&&typeof v==='boolean'));out.codingResults=Object.fromEntries(Object.entries(object(x.codingResults)).filter(([k,v])=>CODING_DRILLS.some(d=>d.id===k)&&v?.passed===true).map(([k,v])=>[k,{passed:true,independent:v.independent===true}]));out.interviewResults=Object.fromEntries(Object.entries(object(x.interviewResults)).filter(([k,v])=>/^\d+$/.test(k)&&v?.attempted===true).map(([k,v])=>[k,{attempted:true,length:Number.isFinite(v.length)?v.length:0}]));out.jobs=Array.isArray(x.jobs)?x.jobs.filter(j=>j&&typeof j.employer==='string'&&typeof j.role==='string').slice(0,1000).map(j=>({employer:j.employer.slice(0,250),role:j.role.slice(0,250),link:typeof j.link==='string'&&/^https?:\/\//i.test(j.link)?j.link.slice(0,2000):'',base:typeof j.base==='number'&&Number.isFinite(j.base)&&j.base>0?j.base:null,location:['kaohsiung','other'].includes(j.location)?j.location:'unknown'})):[];out.evidence=Array.isArray(x.evidence)?x.evidence.filter(e=>e&&typeof e.skill==='string'&&typeof e.url==='string'&&/^https?:\/\//i.test(e.url)).slice(0,1000).map(e=>({skill:e.skill.slice(0,60),url:e.url.slice(0,2000)})):[];out.roleTrack=typeof x.roleTrack==='string'?x.roleTrack:'applied';return out};
