const sqlTasks=[
 {title:'01 · Inspect tested wafers',level:'Basic',prompt:'Return wafer_id, passed and tested for all wafers, ordered by wafer_id.',starter:'SELECT wafer_id, passed, tested\nFROM wafers\nORDER BY wafer_id;',solution:'SELECT wafer_id, passed, tested FROM wafers ORDER BY wafer_id',hint:'Start with SELECT wafer_id, passed, tested FROM wafers. End with ORDER BY wafer_id.'},
 {title:'02 · Filter pressure readings',level:'Basic',prompt:'Return tool_id and pressure for sensor readings with pressure > 104, ordered from lowest to highest pressure.',starter:'SELECT tool_id, pressure\nFROM sensor_logs\nWHERE pressure > 104\nORDER BY pressure;',solution:'SELECT tool_id, pressure FROM sensor_logs WHERE pressure > 104 ORDER BY pressure',hint:'Filter raw sensor_logs using WHERE pressure > 104, then ORDER BY pressure.'},
 {title:'03 · Calculate pooled lot yield',level:'Core interview',prompt:'Return lot_id and pooled die yield (alias yield_rate) for each lot, sorted by lot_id. Use total passed / total tested.',starter:'SELECT lot_id,\n  SUM(passed) * 1.0 / NULLIF(SUM(tested), 0) AS yield_rate\nFROM wafers\nGROUP BY lot_id\nORDER BY lot_id;',solution:'SELECT lot_id, SUM(passed)*1.0/NULLIF(SUM(tested),0) AS yield_rate FROM wafers GROUP BY lot_id ORDER BY lot_id',hint:'Do not AVG individual wafer percentages. Use SUM(passed) / SUM(tested) with GROUP BY lot_id.'},
 {title:'04 · Join wafers to products',level:'Core interview',prompt:'Return wafer_id and product for every wafer, sorted by wafer_id. Join wafers to lots on lot_id.',starter:'SELECT w.wafer_id, l.product\nFROM wafers w\nJOIN lots l ON w.lot_id = l.lot_id\nORDER BY w.wafer_id;',solution:'SELECT w.wafer_id, l.product FROM wafers w INNER JOIN lots l ON w.lot_id=l.lot_id ORDER BY w.wafer_id',hint:'Join by shared lot_id. lot_id should be unique in lots, avoiding a row explosion.'},
 {title:'05 · Window lag by tool',level:'Advanced',prompt:'Return tool_id, event_time, pressure and previous_pressure (previous pressure within each tool, ordered by event_time). Sort results by tool_id and event_time.',starter:'SELECT tool_id, event_time, pressure,\n  LAG(pressure) OVER (PARTITION BY tool_id ORDER BY event_time) AS previous_pressure\nFROM sensor_logs\nORDER BY tool_id, event_time;',solution:'SELECT tool_id,event_time,pressure,LAG(pressure) OVER (PARTITION BY tool_id ORDER BY event_time) AS previous_pressure FROM sensor_logs ORDER BY tool_id,event_time',hint:'LAG() needs PARTITION BY tool_id and ORDER BY event_time. Never mix equipment histories.'},
 {title:'06 · Lots with two or more wafers',level:'Intermediate',prompt:'Return lot_id and wafer_count for lots with at least two wafers, sorted by lot_id.',starter:'SELECT lot_id, COUNT(*) AS wafer_count\nFROM wafers\nGROUP BY lot_id\nHAVING COUNT(*) >= 2\nORDER BY lot_id;',solution:'SELECT lot_id,COUNT(*) AS wafer_count FROM wafers GROUP BY lot_id HAVING COUNT(*) >= 2 ORDER BY lot_id',hint:'Use GROUP BY lot_id; filter the aggregate with HAVING, not WHERE.'},
 {title:'07 · All tools, even unused tools',level:'Intermediate',prompt:'Return tool_id and total_wafers for all tools including tools with zero wafers, sorted by tool_id.',starter:'SELECT t.tool_id, COUNT(w.wafer_id) AS total_wafers\nFROM tools t\nLEFT JOIN wafers w ON t.tool_id = w.tool_id\nGROUP BY t.tool_id\nORDER BY t.tool_id;',solution:'SELECT t.tool_id,COUNT(w.wafer_id) AS total_wafers FROM tools t LEFT JOIN wafers w ON t.tool_id=w.tool_id GROUP BY t.tool_id ORDER BY t.tool_id',hint:'Start with tools and LEFT JOIN wafers. COUNT(w.wafer_id) excludes unmatched nulls.'},
 {title:'08 · Per-tool pressure summary',level:'Intermediate',prompt:'Return tool_id and average_pressure from sensor_logs, sorted by tool_id.',starter:'SELECT tool_id, AVG(pressure) AS average_pressure\nFROM sensor_logs\nGROUP BY tool_id\nORDER BY tool_id;',solution:'SELECT tool_id,AVG(pressure) AS average_pressure FROM sensor_logs GROUP BY tool_id ORDER BY tool_id',hint:'Use AVG(pressure) and GROUP BY tool_id.'}
];
const pyTasks=[
 {title:'01 · Your first yield function',level:'Basic',prompt:'Write Python that prints the yield for 45 passed dies out of 50 tested dies, as the numeric value 0.9.',starter:'passed = 45\ntested = 50\nprint(passed / tested)',expected:'0.9',hint:'Use passed / tested. Print the numeric ratio, not the percent string.'},
 {title:'02 · Group tool readings',level:'Basic',prompt:'Calculate and print the average of [100, 102, 98]. Expected output: 100.0.',starter:'readings = [100, 102, 98]\nprint(sum(readings) / len(readings))',expected:'100.0',hint:'sum(readings) / len(readings) calculates an ordinary mean.'},
 {title:'03 · Raise on a bad denominator',level:'Core interview',prompt:'Write a yield_rate(passed,tested) function that raises ValueError for tested<=0. Call it with (9,10) and print the result 0.9.',starter:'def yield_rate(passed, tested):\n    if tested <= 0 or passed < 0 or passed > tested:\n        raise ValueError("invalid counts")\n    return passed / tested\n\nprint(yield_rate(9, 10))',expected:'0.9',hint:'Validate before dividing; return passed / tested and print yield_rate(9,10).'},
 {title:'04 · Unique lot IDs',level:'Basic',prompt:'Print the number of unique lots in ["L1","L2","L1","L3","L2"]. Expected output: 3.',starter:'lots = ["L1", "L2", "L1", "L3", "L2"]\nprint(len(set(lots)))',expected:'3',hint:'A set keeps one copy of each distinct string.'},
 {title:'05 · Count failing records',level:'Intermediate',prompt:'For outcomes [1,0,1,1,0,0], print the number of failures when 0 means fail. Expected output: 3.',starter:'outcomes = [1, 0, 1, 1, 0, 0]\nprint(sum(x == 0 for x in outcomes))',expected:'3',hint:'Use a condition per item, e.g., sum(x == 0 for x in outcomes).'},
 {title:'06 · Sorted tool names',level:'Basic',prompt:'Print one comma-separated string T01,T02,T03 from ["T03","T01","T02"].',starter:'tools = ["T03", "T01", "T02"]\nprint(",".join(sorted(tools)))',expected:'T01,T02,T03',hint:'Use sorted(...) to order strings, and ",".join(...) to combine them.'}
];
