let lastRenderedRoute;
function resetRouteState(){tutorGeneration++;state.tutorBusy=false;state.navOpen=false;state.lessonSelected=-1;state.lessonDraft='';state.practiceFeedback='';state.quizFeedback='';state.chat=[];state.tutorText=''}
