function handleCoding(action,target){if(action==='coding-scroll'){document.getElementById('coding-drills')?.scrollIntoView({behavior:'smooth'});return}if(action==='coding-stop'){cancelCoding?.();return}if(state.codingBusy)return;const t=CODING_DRILLS[state.codingIndex];if(action==='coding-pick'){state.codingIndex=Number(target.dataset.index);state.codingDraft=null;state.codingOutput='';state.codingHint=false;state.codingSolution=false;}else if(action==='coding-mode'){state.codingMode=target.dataset.mode;state.codingDraft=null;state.codingOutput='';state.codingHint=false;state.codingSolution=false;}else if(action==='coding-reset'){draftRemove('drill:'+state.codingMode+':'+t.id);state.codingDraft=null;state.codingOutput='';state.codingHint=false;state.codingSolution=false;}else if(action==='coding-hint'&&state.codingMode==='guided'){state.codingHint=true;}else if(action==='coding-solution'&&state.codingMode==='guided'){state.codingSolution=true;}else if(action==='coding-run'){runCoding();return;}render();document.getElementById('coding-drills')?.scrollIntoView({block:'start'});}
let cancelCoding=null,cancelLab=null;
async function runCoding(){if(state.codingBusy)return;const t=CODING_DRILLS[state.codingIndex],code=document.getElementById('coding-editor')?.value??state.codingDraft??t.starter;state.codingDraft=code;if(!code.trim()){state.codingOutput='Write an implementation before running tests.';render();return;}state.codingBusy=true;state.codingOutput='Running assertions…';render();let worker;
 try{const result=await new Promise((resolve,reject)=>{worker=new Worker('/src/'+(t.language==='python'?'python-worker.js':'javascript-worker.js'));const settle=(fn,value)=>{clearTimeout(timer);cancelCoding=null;fn(value)};const timer=setTimeout(()=>settle(reject,new Error('Timed out. Check for an infinite loop or runtime loading problem.')),t.language==='python'?65000:5000);cancelCoding=()=>settle(reject,new Error('Stopped by learner.'));worker.onmessage=e=>{if(e.data?.id===1)settle(resolve,e.data)};worker.onerror=()=>settle(reject,new Error('Worker failed to load. Check network or browser settings.'));worker.postMessage({id:1,code,tests:t.tests});});if(result.ok&&result.testPassed){const old=state.codingResults[t.id]||{};state.codingResults[t.id]={passed:true,independent:old.independent||state.codingMode==='independent'};store();state.codingOutput='PASS · All programmed assertions passed. Now explain your solution and its edge cases.\n'+(result.output||'');}else{state.codingOutput='NOT PASSED · Read the first error or assertion and trace the failing input.\n'+String(result.output||'Unknown error').slice(0,10000);}}catch(e){state.codingOutput='Execution error: '+String(e.message||e);}finally{worker?.terminate();cancelCoding=null;state.codingBusy=false;if(currentRoute()==='coding')render();if(currentRoute()==='coding')document.getElementById('coding-drills')?.scrollIntoView({block:'start'});}}

function renderWorkspace(){if(currentRoute()==='workspace')render()}
function render(){destroyEditors();const route=currentRoute();lastRenderedRoute=route;const slash=route.indexOf('/'),kind=slash<0?route:route.slice(0,slash),arg=slash<0?undefined:route.slice(slash+1);let page;switch(kind){case 'workspace':page=workspaceView();break;case 'dashboard':page=dashboard();break;case 'coding':page=codingHub();break;case 'book':page=book();break;case 'pro':page=professionalHub();break;case 'interview':page=interviewHub();break;case 'module':page=moduleView(arg);break;case 'lesson':page=lessonView(arg);break;case 'software':page=software();break;case 'guide':page=guideView(arg);break;case 'labs':page=labs();break;case 'practice':page=practice();break;case 'portfolio':page=portfolio();break;case 'project':page=projectView(arg);break;case 'career':page=career();break;case 'glossary':page=glossaryView();break;case 'search':page=searchView(arg||'');break;default:page=dashboard()}document.getElementById('app').innerHTML=frame(page);if(kind==='workspace'){const f=currentFile();enhanceEditor('workspace-code',{language:f.language,filename:f.name,onSave:updateFile,onRun:()=>workspaceAction('run',{},renderWorkspace)});mountWorkspacePreview();}else if(kind==='coding'){const t=CODING_DRILLS[state.codingIndex];enhanceEditor('coding-editor',{language:t.language,filename:t.language==='python'?'solution.py':'solution.js',key:'drill:'+state.codingMode+':'+t.id,independent:state.codingMode==='independent',onRun:()=>{if(!state.codingBusy)runCoding()}});}else if(kind==='labs'){enhanceEditor('lab-code',{language:state.labTab,filename:state.labTab==='sql'?'query.sql':'solution.py',key:'lab:'+state.labTab+':'+state.labIndex,onRun:runLab});}if(state.chat.length){const c=document.getElementById('chat-scroll');if(c)c.scrollTop=c.scrollHeight}}
function quizReview(l){if(state.lessonSelected<0)return 'Choose an answer first.';if(state.lessonSelected===l.quiz.correct){state.quizzes[l.id]=true;store();return `Correct. ${l.quiz.why} You have passed this knowledge check.`}return `Not quite. You selected “${l.quiz.options[state.lessonSelected]}”. The correct answer is “${l.quiz.options[l.quiz.correct]}”. Why: ${l.quiz.why}\n\nRecall this common misconception: ${l.pitfall}\nTry explaining the correct answer in your own words, then reattempt.`}
function draftReview(l,text){if(text.trim().length<12)return 'Your answer is too short to evaluate meaningfully. State your assumptions, the method and the conclusion; then compare it with the model reasoning.';const common=['the','and','for','with','from','this','that','would','their','which','what','they','into','there','about','while','because','then','data','example','should','using','when','where','first','also','have','more','only'];const terms=[...new Set((l.answer.toLowerCase().match(/[a-z]{4,}/g)||[]).filter(x=>!common.includes(x)))];const hit=terms.filter(t=>text.toLowerCase().includes(t));return `Guided self-check (not a definitive AI grade): You mention ${hit.slice(0,5).join(', ')||'few of the model answer’s technical terms'}. ${hit.length>=3?'Your answer contains several relevant concepts. Verify that your assumptions and result match the worked reasoning.':'Your reasoning may be missing key distinctions. Compare it with the model answer and check '+terms.slice(0,3).join(', ')+'.'}\n\nA common failure mode to examine: ${l.pitfall}\n\nFor precise line-by-line review, choose “Ask FabMentor”; remote AI requires the site owner to configure an API key.`}
function localCoach(l,question,attempt){const q=(question||'').toLowerCase();if(!l)return 'Open a textbook lesson and tell me your attempt so I can review it in context.';if(q.includes('wrong')||q.includes('mistake')||q.includes('error')){let detail=attempt&&attempt.trim().length>8?draftReview(l,attempt):'I do not yet have your full attempt. Paste your reasoning or code so I can compare its assumptions.';return `LOCAL COACH · DIAGNOSTIC\n\n${detail}\n\nLesson-specific likely pitfall: ${l.pitfall}\n\nWhat to try next: ${l.task}\n\nNote: This offline response is a heuristic, not verified line-by-line AI debugging.`}if(q.includes('hint'))return `LOCAL COACH · ONE HINT\n\nStart from the definition in the lesson. ${l.example.split(/[.!?]\s/)[0]}.\n\nCheck the common mistake before choosing a formula: ${l.pitfall}`;return `LOCAL COACH · EXPLANATION\n\n${l.theory.split(/\n\s*\n/)[0]}\n\nWorked example: ${l.example}\n\nYour next question: ${l.task}\n\nFor a personalized explanation beyond these lesson notes, enable the remote AI tutor on Vercel.`}
let tutorGeneration=0;
async function askMentor(prompt){if(state.tutorBusy)return;const generation=++tutorGeneration;const route=currentRoute();const l=getLesson(currentRoute().split('/')[1]);if(!l)return;const attempt=document.getElementById('practice-draft')?.value||state.lessonDraft;state.tutorText='';state.chat.push({role:'user',text:prompt});state.tutorBusy=true;render();let answer;try{const response=await fetch('/api/tutor',{method:'POST',headers:{'Content-Type':'application/json','X-FabReady-Tutor-Code':state.tutorAccessCode},body:JSON.stringify({question:prompt,lessonTitle:l.title,lessonContent:l.theory+'\n'+l.pitfall+'\n'+l.answer,learnerAttempt:attempt,mode:prompt.toLowerCase().includes('wrong')?'debug':'teach'}),signal:AbortSignal.timeout(23000)});if(!response.ok)throw new Error('AI not configured');let json=await response.json();if(typeof json.answer!=='string'||!json.answer.trim())throw new Error('Missing response');answer=json.answer}catch{answer=localCoach(l,prompt,attempt)}if(generation!==tutorGeneration||currentRoute()!==route)return;state.chat.push({role:'assistant',text:answer});state.tutorBusy=false;render()}
let sqlWorker=null,serial=0;
function runWorker(kind,code,expected,tests){return new Promise((resolve,reject)=>{
 const isSql=kind==='sql';let worker=isSql?sqlWorker:null;
 if(!worker){worker=new Worker('/src/'+(isSql?'sql-worker.js':'python-worker.js'));if(isSql)sqlWorker=worker;}
 const id=++serial;
 const cleanup=()=>{clearTimeout(timer);worker.removeEventListener('message',message);worker.removeEventListener('error',error);cancelLab=null;};
 const fail=reason=>{cleanup();worker.terminate();if(isSql)sqlWorker=null;reject(new Error(reason));};
 const message=e=>{if(e.data?.id!==id)return;cleanup();if(!isSql||!e.data.ok){worker.terminate();if(isSql)sqlWorker=null;}resolve(e.data);};
 const error=()=>fail('Runtime could not load. Check internet access and browser console.');
 const timer=setTimeout(()=>fail('Execution timed out. Check for an infinite loop or unavailable runtime.'),isSql?25000:65000);
 cancelLab=()=>fail('Stopped by learner.');worker.addEventListener('message',message);worker.addEventListener('error',error);
 try{worker.postMessage(isSql?{id,sql:code,expected}:{id,code,tests:tests||''});}catch(e){fail(String(e.message||e));}
})}
async function runLab(){if(state.labBusy)return;const kind=state.labTab,index=state.labIndex,task=(kind==='sql'?sqlTasks:pyTasks)[index],field=document.getElementById('lab-code');state.labCode=field?.value||'';if(!state.labCode.trim()){toast('Write code before running it.');return}state.labBusy=true;state.labOutput={message:kind==='sql'?'Loading SQLite engine and executing query…':'Loading local Pyodide, then running Python…'};render();try{let res=await runWorker(kind,state.labCode,kind==='sql'?task.solution:null,kind==='python'?task.tests:null);if(!res.ok){let err=res.error||res.output||'Execution error';let cause=/no such column/i.test(err)?'Check column names in the synthetic schema and the spelling of your SELECT.':/syntax error/i.test(err)?'Look near the reported token for an extra comma, misspelled SQL keyword, or missing parentheses.':/NameError|not defined/i.test(err)?'Python names are case-sensitive. Check definition and order of execution.':'';state.labOutput={error:err+(cause?'\n\nSuggested fix: '+cause:'')}}else if(kind==='sql'){const passed=res.correct;state.labOutput={table:res.result,message:passed?'✓ Correct output and column names! Your ordered result matches the reference solution.':'Query executed. Your output differs from the expected result. Recheck row filters, JOIN cardinality, grouping, ordering and required column aliases. Click “Show a hint” for a targeted next step.',success:passed};if(passed){state.labs[kind+':'+index]=true;store()}}else{const output=res.output||'',normalize=x=>String(x).replace(/\s+/g,' ').trim(),passed=(task.tests?res.testPassed:normalize(output)===normalize(task.expected));state.labOutput={output,message:passed?(task.tests?'✓ All programmed assertion tests passed. Explain the algorithm and its complexity independently.':'✓ Correct program output! The result matches the challenge.'):'Python executed, but the output did not pass the challenge. Check exceptions, types, edge cases, expected output, and algorithm complexity.',success:passed};if(passed){state.labs[kind+':'+index]=true;store()}}}catch(e){state.labOutput={error:String(e.message||e)}}state.labBusy=false;if(currentRoute()==='labs')render()}
function newExam(){state.exam=[];state.examPicks={};state.examDone=false;render()}
function downloadProgress(){const payload={exportedAt:new Date().toISOString(),codingResults:state.codingResults,completed:state.completed,quizzes:state.quizzes,labs:state.labs,projects:state.projects,guides:state.guides,jobs:state.jobs,evidence:state.evidence,gates:state.gates,interviewResults:state.interviewResults,roleTrack:state.roleTrack};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='fabready-progress.json';document.body.append(a);a.click();a.remove();URL.revokeObjectURL(url);toast('Progress exported as JSON. Keep your backup private.')}

document.addEventListener('click',e=>{const target=e.target.closest('[data-work],[data-route],[data-action],[data-filter],[data-soft-filter],[data-lab-tab],[data-lab-index]');if(!target)return;if(target.dataset.work){e.preventDefault();workspaceAction(target.dataset.work,target,renderWorkspace);return}if(target.dataset.route){e.preventDefault();setRoute(target.dataset.route);return}if(target.dataset.filter){state.filter=target.dataset.filter;render();return}if(target.dataset.softFilter){state.softwareFilter=target.dataset.softFilter;render();return}if(target.dataset.labTab){if(state.labBusy)return;state.labTab=target.dataset.labTab;state.labIndex=0;state.labCode=null;state.labOutput=null;render();return}if(target.dataset.labIndex!==undefined){if(state.labBusy)return;state.labIndex=Number(target.dataset.labIndex);state.labCode=null;state.labOutput=null;render();return}const action=target.dataset.action;if(action==='skip-main'){e.preventDefault();document.getElementById('main-content')?.focus();return}if(action?.startsWith('coding-')){e.preventDefault();handleCoding(action,target);return}const l=getLesson(currentRoute().split('/')[1]);if(action==='menu'){state.navOpen=!state.navOpen;render();return}if(action==='complete'&&l){state.completed[l.id]=target.checked;store();render();toast(target.checked?'Lesson marked complete':'Lesson marked incomplete');return}if(action==='quiz-pick'){state.lessonSelected=Number(target.dataset.index);render();return}if(action==='quiz-check'&&l){state.quizFeedback=quizReview(l);render();return}if(action==='review-draft'&&l){state.lessonDraft=document.getElementById('practice-draft')?.value||'';state.practiceFeedback=draftReview(l,state.lessonDraft);render();return}if(action==='mentor-quick'){state.lessonDraft=document.getElementById('practice-draft')?.value||state.lessonDraft;askMentor(target.dataset.prompt);return}if(action==='mentor-send'){state.lessonDraft=document.getElementById('practice-draft')?.value||state.lessonDraft;let val=document.getElementById('mentor-input')?.value.trim();if(val)askMentor(val);else toast('Type your question to FabMentor.');return}if(action==='ask-mistake'){state.lessonDraft=document.getElementById('practice-draft')?.value||state.lessonDraft;askMentor('Please examine the first incorrect step in my answer and explain why, with one minimal hint.');return}if(action==='copy-code'&&l){navigator.clipboard?.writeText(l.code).then(()=>toast('Example copied.')).catch(()=>toast('Select and copy the code manually.'));return}if(action==='lab-from-lesson'&&l){if(state.labBusy){toast('Stop the running lab first.');return}state.labTab='sql';state.labIndex=0;state.labCode=l.code;state.labOutput=null;setRoute('labs');return}if(action==='guide-check'){state.guides[target.dataset.key]=target.checked;store();render();return}if(action==='project-check'){state.projects[target.dataset.key]=target.checked;store();render();return}if(action==='run-lab'){runLab();return}if(action==='stop-lab'){cancelLab?.();return}if(action==='lab-hint'){if(state.labBusy)return;const t=(state.labTab==='sql'?sqlTasks:pyTasks)[state.labIndex];state.labCode=document.getElementById('lab-code')?.value||state.labCode;state.labOutput={message:'HINT: '+t.hint};render();return}if(action==='reset-code'){if(state.labBusy)return;const t=(state.labTab==='sql'?sqlTasks:pyTasks)[state.labIndex];draftRemove('lab:'+state.labTab+':'+state.labIndex);state.labCode=t.starter;state.labOutput=null;render();return}if(action==='copy-lab'){if(!navigator.clipboard){toast('Select and copy the code manually.');return}navigator.clipboard.writeText(document.getElementById('lab-code')?.value||'').then(()=>toast('Code copied.')).catch(()=>toast('Select and copy the code manually.'));return}if(action==='new-exam'){newExam();return}if(action==='exam-pick'){state.examPicks[Number(target.dataset.q)]=Number(target.dataset.index);render();return}if(action==='exam-submit'){if(Object.keys(state.examPicks).length<10){toast('Please answer all ten questions first.');return}state.examDone=true;render();return}if(action==='role-track'){state.roleTrack=target.dataset.role;store();render();return}if(action==='gate-check'){state.gates[target.dataset.key]=target.checked;store();render();return}if(action==='remove-evidence'){state.evidence.splice(Number(target.dataset.index),1);store();render();return}if(action==='interview-next'){state.interviewIndex=(state.interviewIndex+1)%INTERVIEW_CASES.length;state.interviewFeedback='';state.interviewText='';render();return}if(action==='interview-pick'){state.interviewIndex=Number(target.dataset.index);state.interviewFeedback='';state.interviewText='';render();return}if(action==='interview-review'){state.interviewText=document.getElementById('interview-answer')?.value||'';state.interviewFeedback=interviewFeedback(INTERVIEW_CASES[state.interviewIndex],state.interviewText);state.interviewResults[state.interviewIndex]={attempted:true,length:state.interviewText.length};store();render();return}if(action==='remove-job'){state.jobs.splice(Number(target.dataset.index),1);store();render();return}if(action==='export-progress'){downloadProgress();return}if(action==='restore-progress'){document.getElementById('progress-import')?.click();return}});
document.addEventListener('submit',e=>{if(e.target.id==='evidence-form'){e.preventDefault();const d=new FormData(e.target);const skill=String(d.get('skill')||'').slice(0,60),url=safeUrl(String(d.get('url')||'').trim());if(!url){toast('Use a valid https:// or http:// evidence link.');return}state.evidence.push({skill,url});store();render();toast('Evidence link saved locally. It has not been independently reviewed.');return}if(e.target.id!=='job-form')return;e.preventDefault();const d=new FormData(e.target),employer=String(d.get('employer')||'').trim(),role=String(d.get('role')||'').trim(),link=String(d.get('link')||'').trim();if(!employer||!role)return;const value=String(d.get('base')||'').trim(),base=value?Number(value):null;const location=String(d.get('location')||'unknown');if(base!==null&&(!Number.isFinite(base)||base<1||base>5000000)){toast('Enter a realistic fixed monthly base in NT$, or leave unknown.');return}state.jobs.push({employer,role,link:safeUrl(link)||'',base,location});store();render();toast('Saved locally. Verify actual Kaohsiung location.')});
document.addEventListener('change',async e=>{if(e.target.id==='progress-import'){const f=e.target.files?.[0];if(!f)return;try{if(f.size>50000000)throw Error('Backup too large.');const raw=JSON.parse(await f.text());if(!raw||typeof raw!=='object'||!raw.completed||!raw.quizzes)throw Error('Not a FabReady progress backup.');const restored=validProgress(raw);if(!window.confirm('Replace your current progress with this backup? Export first if needed.'))return;Object.assign(state,restored);const persisted=store();render();toast(persisted?'Progress restored.':'Progress restored in memory only. Export a backup before reloading.')}catch(err){toast('Restore failed: '+err.message)}finally{e.target.value=''}return;}if(e.target.id==='workspace-test-toggle'||e.target.id==='workspace-import')workspaceInput(e.target,renderWorkspace);if(e.target.id==='guide-search'){state.guideSearch=e.target.value;render()}});
document.addEventListener('input',e=>{if(e.target.id?.startsWith('workspace-')){workspaceInput(e.target)}else if(e.target.id==='coding-editor'){state.codingDraft=e.target.value}else if(e.target.id==='tutor-access-code'){state.tutorAccessCode=e.target.value}else if(e.target.id==='guide-search'){state.guideSearch=e.target.value;const start=e.target.selectionStart;render();let field=document.getElementById('guide-search');field?.focus();field?.setSelectionRange(start,start)}else if(e.target.id==='lab-code'){state.labCode=e.target.value}else if(e.target.id==='practice-draft'){state.lessonDraft=e.target.value}else if(e.target.id==='mentor-input'){state.tutorText=e.target.value}else if(e.target.id==='interview-answer'){state.interviewText=e.target.value}});
document.addEventListener('keydown',e=>{if(e.target.id==='global-search'&&e.key==='Enter'){let q=e.target.value.trim();if(q)setRoute('search/'+encodeURIComponent(q))}if((e.key==='Enter'||e.key===' ')&&e.target.dataset.route&&e.target.getAttribute('role')==='button'){e.preventDefault();setRoute(e.target.dataset.route)}});
window.addEventListener('hashchange',()=>{if(currentRoute()===lastRenderedRoute)return;resetRouteState();render()});
